    candidato.notificadoPorAliado = true;
    candidato.horaPropuestaAliado = candidato.hora;
    candidato.llegada = candidato.hora;
    desvincularEventoGuionado(candidato);
    candidato.notificacionValidada = true;
    candidato.arriboResolucion = 'aprobada';
    candidato.arriboConfirmadoEn = addMinutesHM(candidato.hora, plan.confirmacionMin);
    candidato.asistenciaBodegaFalsaAlerta = true;
