/* ---------------- Utilidades ---------------- */
function parseDT(fecha, hhmm) { return new Date(fecha + 'T' + hhmm + ':00'); }
function minutesDiff(a, b) { return (a.getTime() - b.getTime()) / 60000; }
function fmtTimeHM(d) { return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); }
function fmtTime12(hhmm) {
  if (!hhmm) return '—';
  var parts = hhmm.split(':'); var h = parseInt(parts[0], 10);
  var ampm = h >= 12 ? 'PM' : 'AM'; var h12 = h % 12; if (h12 === 0) h12 = 12;
  return String(h12).padStart(2, '0') + ':' + parts[1] + ' ' + ampm;
}
function fmtClock(d, timeZone) {
  var opts = { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true };
  if (timeZone) opts.timeZone = timeZone;
  return new Intl.DateTimeFormat('en-US', opts).format(d);
}
var MESES_LARGO = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
function fmtDateLong(fechaStr) {
  var p = fechaStr.split('-'); var y = parseInt(p[0], 10), mo = parseInt(p[1], 10), d = parseInt(p[2], 10);
  return d + ' de ' + MESES_LARGO[mo - 1] + ' de ' + y;
}
/* Formato largo para el Rango de Fechas de Historial (ver historialRangoPreset) — un solo día ("Ayer") se
   muestra igual que fmtDateLong; un rango real muestra ambos extremos unidos por un guion largo. */
function fmtDateRangeLong(desde, hasta) {
  return desde === hasta ? fmtDateLong(desde) : (fmtDateLong(desde) + ' – ' + fmtDateLong(hasta));
}
