function t(key, fallback) {
  var dict = TRANSLATIONS[state.uiLang] || TRANSLATIONS.es;
  if (dict[key] != null) return dict[key];
  if (TRANSLATIONS.es[key] != null) return TRANSLATIONS.es[key];
  return fallback !== undefined ? fallback : key;
}
var FLAG_ES_SVG = '<svg width="16" height="12" viewBox="0 0 16 12" aria-hidden="true"><rect width="16" height="12" fill="#AA151B"/><rect y="3" width="16" height="6" fill="#F1BF00"/></svg>';
