  if (!route) return;
  var m = getMensajero(route.mensajeroId);
  document.getElementById('retiroRutaId').value = routeId;
  document.getElementById('retiroNote').textContent = route.id + ' · ' + m.nombre + ' · ' + route.vehiculo;
