  var descripcion = m.nombre + ' (' + m.placa + ') · ' + m.aliado + (esFlotaPropia(m.aliado) ? ' [Propio - Melonn]' : '') + ' — ' + detalle;
  var prioridad = alertPriorityInfo(a);
