    rec.motivoHtml = escapeHtml(s.motivo) + (s.motivoRechazo ? (' — Motivo del rechazo: ' + escapeHtml(s.motivoRechazo)) : '');
    rec.resultadoHtml = resultLabel;
    rec.resueltoPorTxt = s.resueltoPor ? (escapeHtml(s.resueltoPor) + (s.resueltoPorRol ? ' (' + s.resueltoPorRol + ')' : '')) : '—';
