    rec.resueltaTxt = c.resueltoEn ? ((c.resueltoFecha ? fmtDateLong(c.resueltoFecha) + ' · ' : '') + c.resueltoEn) : '—';
    rec.resueltoFecha = c.resueltoFecha || '';
