  document.getElementById('formGestorAvisos').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('avisos.manage')) return;
    var texto = document.getElementById('avisoTexto').value.trim();
    if (!texto) return;
    var tipo = document.querySelector('#avisoTipoSegment button.active').dataset.tipo;
    var paisScope = document.querySelector('#avisoPaisSegment button.active').dataset.pais;
    var todosAliados = document.getElementById('avisoTodosAliados').checked;
    var aliadosScope = todosAliados ? [] : Array.from(document.querySelectorAll('#avisoAliadosChecklist input:checked')).map(function (i) { return i.value; });
    if (!todosAliados && !aliadosScope.length) { toast('warn', 'Selecciona al menos un aliado', 'Marca "Todos los aliados" o elige uno o más aliados específicos.'); return; }
    var todasBodegas = document.getElementById('avisoTodasBodegas').checked;
    var bodegaScope = todasBodegas ? [] : Array.from(document.querySelectorAll('#avisoBodegasChecklist input:checked')).map(function (i) { return i.value; });
    if (!todasBodegas && !bodegaScope.length) { toast('warn', 'Selecciona al menos una bodega', 'Marca "Todas las bodegas" o elige una o más bodegas específicas.'); return; }
    var modo = document.querySelector('#avisoModoSegment button.active').dataset.modo;
    /* 'inmediato': la hora de inicio es AHORA MISMO (el instante de guardar, sobre el reloj simulado de
       GRAVITY) -- 'programado': la fecha/hora que Planner eligió en el formulario. */
    var inicioProgramado;
    if (modo === 'programado') {
      var fechaInicio = document.getElementById('avisoFechaInicio').value;
      var horaInicio = document.getElementById('avisoHoraInicio').value;
      if (!fechaInicio || !horaInicio) { toast('warn', 'Falta la fecha/hora de inicio', 'Completa "Fecha de inicio" y "Hora de inicio" para el modo Programado.'); return; }
      inicioProgramado = parseDT(fechaInicio, horaInicio).toISOString();
    } else {
      inicioProgramado = state.now.toISOString();
    }
    var recurrenteDiario = document.getElementById('avisoRecurrenteDiario').checked;
    var duracionOpcion = document.getElementById('avisoExpiracion').value;
    var activo = document.getElementById('avisoActivo').checked;
    /* Edición de un comunicado existente (state.comunicadoEditandoId, ver populateComunicacionesForm):
       conserva id/creadoPor/creadoEn/archivado ORIGINALES -- la trazabilidad de autoría es del acto de
       CREACIÓN, no se reescribe por una edición posterior. Uno nuevo genera su propio id y autoría ahora. */
    var existente = state.comunicadoEditandoId ? state.configSettings.comunicados.find(function (c) { return c.id === state.comunicadoEditandoId; }) : null;
    var draftAviso = {
      id: existente ? existente.id : nextComunicadoId(),
      activo: activo, texto: texto, tipo: tipo, paisScope: paisScope, bodegaScope: bodegaScope, aliadosScope: aliadosScope,
      modo: modo, inicioProgramado: inicioProgramado, recurrenteDiario: recurrenteDiario, duracionOpcion: duracionOpcion,
      archivado: existente ? !!existente.archivado : false,
      creadoPor: existente ? existente.creadoPor : state.user.nombre,
      creadoPorRol: existente ? existente.creadoPorRol : state.user.role,
      creadoEn: existente ? existente.creadoEn : state.now.toISOString()
    };
    /* Ver requerimiento "Modal de Confirmación al Guardar/Editar en Comunicaciones": el guardado ya NO es
       inmediato al enviar el formulario -- este solo valida y arma el resumen; la escritura real a
       state.configSettings.comunicados queda en btnConfirmarAvisoPublicar. */
    avisoPendienteConfirmacion = { draft: draftAviso, esNuevo: !existente, fechaInicio: fechaInicio, horaInicio: horaInicio };
    abrirConfirmacionAviso(draftAviso);
  });
  document.getElementById('btnConfirmarAvisoPublicar').addEventListener('click', function () {
    if (!avisoPendienteConfirmacion) { closeModal(); return; }
    var pend = avisoPendienteConfirmacion;
    if (pend.esNuevo) state.configSettings.comunicados.push(pend.draft);
    else {
      var idx = state.configSettings.comunicados.findIndex(function (c) { return c.id === pend.draft.id; });
      if (idx !== -1) state.configSettings.comunicados[idx] = pend.draft; else state.configSettings.comunicados.push(pend.draft);
    }
    persistConfigSettings();
    /* Republicar/editar un comunicado vuelve a mostrarlo aunque alguien ya hubiera cerrado una versión
       anterior con la (X) -- el cierre "por sesión" aplica a la versión que estaba vigente en ese momento. */
    delete state.comunicadosDismissed[pend.draft.id];
    var mensajeToast = !pend.draft.activo ? 'El comunicado quedó guardado pero no se mostrará hasta activarlo.'
      : pend.draft.modo === 'programado' ? 'El comunicado quedará visible a partir del ' + fmtDateLong(pend.fechaInicio) + ' a las ' + fmtTime12(pend.horaInicio) + '.'
      : 'El comunicado ya está visible para el alcance seleccionado.';
    toast(pend.draft.activo ? 'ok' : 'warn', pend.draft.activo ? 'Comunicado guardado' : 'Comunicado guardado (inactivo)', mensajeToast);
    avisoPendienteConfirmacion = null;
    closeModal();
    syncAndRender(true);
  });

