  document.getElementById('cumplimientoBodegaAliado').addEventListener('change', function () { state.cumplimientoBodegaFiltroAliado = this.value; renderCumplimiento(); });
  document.getElementById('cumplimientoBodegaMensajero').addEventListener('change', function () { state.cumplimientoBodegaFiltroMensajero = this.value; renderCumplimiento(); });
