  document.getElementById('npBodega').addEventListener('change', function () { refreshNpAliadoOptions(); refreshNpRutaOptions(); refreshNpFieldsForTipo(); });
  document.getElementById('npAliado').addEventListener('change', function () { refreshNpRutaOptions(); refreshNpFieldsForTipo(); });
  document.getElementById('npTipo').addEventListener('change', refreshNpFieldsForTipo);
  document.getElementById('npRuta').addEventListener('change', function () { if (document.getElementById('npTipo').value === 'enroque') refreshNpFieldsForTipo(); });
  document.getElementById('npMasivaTodosAliados').addEventListener('change', refreshNpMasivaFields);
  document.getElementById('formNuevaSolicitudPlanner').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('solicitud.create.planner')) return;
    var tipo = document.getElementById('npTipo').value;
    /* Ver requerimiento "Prompt Consolidador Maestro...", Bloque 3 ("Reprogramación Masiva de Ventana"):
       opera sobre Bodega + varios Aliados + Franjas, nunca sobre UNA sola ruta -- se resuelve por completo
       aquí mismo, sin tocar la lógica de los otros 4 tipos (de un solo route.solicitud) más abajo. Se
       reparte en UNA solicitud general por Aliado elegido (fan-out), nunca una sola solicitud compartida,
       para que cada Aliado decida de forma independiente sobre SU PROPIA flota -- si Cordiandina acepta
       antes que Rapiboy responda, las rutas de Rapiboy no deben moverse todavía (ver aplicarSolicitudGeneral/
       resolverSolicitudGeneral, que resuelven cada una por separado). */
    if (tipo === 'reprogramacion_masiva') {
      var sedeMasiva = document.getElementById('npBodega').value;
      var motivoMasiva = document.getElementById('npMotivo').value.trim();
      if (!motivoMasiva) return;
      var franjasMasiva = Array.from(document.querySelectorAll('.np-masiva-franja:checked')).map(function (el) { return el.value; });
      if (!franjasMasiva.length) { toast('warn', 'Selecciona al menos una franja', 'Elige al menos una franja horaria para desplazar.'); return; }
      var todosAliadosMasiva = document.getElementById('npMasivaTodosAliados').checked;
      var poolMasiva = routesEligiblesPlannerEnBodega(sedeMasiva).filter(function (r) { return r.fecha === TODAY_STR; });
      var aliadosDisponiblesMasiva = Array.from(new Set(poolMasiva.map(function (r) { return getMensajero(r.mensajeroId).aliado; })));
      var aliadosObjetivo = todosAliadosMasiva
        ? aliadosDisponiblesMasiva
        : Array.from(document.querySelectorAll('.np-masiva-aliado:checked')).map(function (el) { return el.value; });
      if (!aliadosObjetivo.length) { toast('warn', 'Selecciona al menos un Aliado', 'Elige "Todos los aliados" o marca al menos uno de la lista.'); return; }
      var desplazamientoMasiva = parseInt(document.getElementById('npMasivaDesplazamiento').value, 10);
      aliadosObjetivo.forEach(function (aliadoObjetivo) {
        state.solicitudesGenerales.push({
          id: nextSolicitudGeneralId(), tipo: 'reprogramacion_masiva', estado: 'pendiente',
          aliado: aliadoObjetivo, motivo: motivoMasiva, fecha: TODAY_STR,
          solicitadoPor: state.user.nombre, solicitadoEn: fmtClock(state.now), origen: 'planner',
          detalle: { sede: sedeMasiva, franjas: franjasMasiva, desplazamientoMinutos: desplazamientoMasiva }
        });
      });
      toast('warn', 'Reprogramación masiva enviada', aliadosObjetivo.length + ' aliado(s) de ' + sedeMasiva + ' recibieron la propuesta de desplazar +' + desplazamientoMasiva + ' min — a la espera de su respuesta.');
      closeModal();
      syncAndRender(true);
      return;
    }
    var routeId = document.getElementById('npRuta').value;
    var route = state.turnos.find(function (r) { return r.id === routeId; });
    if (!route) { toast('warn', 'Selecciona un turno', 'Elige la Bodega, el Aliado y el Mensajero/Turno sobre el que quieres solicitar el cambio.'); return; }
    if (route.solicitud && route.solicitud.estado === 'pendiente') { toast('warn', 'Solicitud ya enviada', route.id + ' ya tiene una solicitud pendiente de respuesta.'); closeModal(); return; }
    /* Segunda barrera (ver routesEligiblesPlannerEnBodega, que ya excluye estas rutas del selector): un
       turno cerrado en Incumplimiento Confirmado o Sin Reemplazo queda inmutable. */
    var codeNp = computeEstado(route).code;
    if (codeNp === 'afectacion_confirmada' || codeNp === 'sin_reemplazo') { toast('warn', 'Turno cerrado', route.id + ' quedó cerrado en Incumplimiento Confirmado — ya no admite Cancelar, Reprogramar, Cambio de Mensajero ni Intercambio de Turno.'); closeModal(); return; }
    var motivo = document.getElementById('npMotivo').value.trim();
    if (!motivo) return;
    var nuevaHora = tipo === 'reprogramacion' ? document.getElementById('npNuevaHora').value : null;
    if (tipo === 'reprogramacion' && !nuevaHora) return;
    var mensajeroPropuestoNp = null;
    if (tipo === 'cambio_mensajero') {
      mensajeroPropuestoNp = {
        nombre: document.getElementById('npCmNombre').value.trim(), telefono: document.getElementById('npCmTelefono').value.trim(),
        cedula: document.getElementById('npCmCedula').value.trim(), placa: document.getElementById('npCmPlaca').value.trim(),
        sede: route.sede, vehiculo: route.vehiculo
      };
      if (!mensajeroPropuestoNp.nombre || !mensajeroPropuestoNp.telefono || !mensajeroPropuestoNp.cedula || !mensajeroPropuestoNp.placa) {
        toast('warn', 'Completa los datos del mensajero propuesto', 'Nombre, teléfono, cédula y placa son obligatorios.'); return;
      }
    }
    var enroqueConRouteIdNp = null;
    if (tipo === 'enroque') {
      enroqueConRouteIdNp = document.getElementById('npEnroqueRuta').value;
      if (!enroqueConRouteIdNp) { toast('warn', 'Selecciona un turno', 'Elige el turno con el que quieres intercambiar mensajeros.'); return; }
    }
    /* origen:'planner' (mismo valor ya usado en rechazarCuotaPlanner) — nunca 'aliado', así resolverSolicitud/
       unifiedFromRouteSolicitud dirigen correctamente la aprobación/rechazo hacia el Aliado dueño del turno,
       igual que ya ocurre con las solicitudes origen:'admin' creadas desde Consolidado. solicitadoPor guarda el
       nombre real del Planner (no un texto genérico) para que nombreConRol la muestre como "Nombre (Planner)"
       en la trazabilidad — mismo criterio que cualquier otra solicitud creada por un usuario real de USERS. */
    var solicitud = {
      tipo: tipo, estado: 'pendiente', motivo: motivo, horaAnterior: route.hora, nuevaHora: nuevaHora,
      mensajeroPropuesto: mensajeroPropuestoNp, enroqueConRouteId: enroqueConRouteIdNp,
      solicitadoPor: state.user.nombre, solicitadoEn: fmtClock(state.now), solicitadaDesdeHM: fmtTimeHM(state.now), fecha: TODAY_STR, origen: 'planner'
    };
    if (tipo === 'reprogramacion') solicitud.evaluacionAntelacion = reprogramacionClasificacion(route);
    route.solicitud = solicitud;
    registrarHistorialCambio(route, { tipo: tipo, accion: 'solicitada', motivo: motivo, horaAnterior: route.hora, horaPropuesta: nuevaHora, por: state.user.nombre, rol: state.user.role });
    var toastMsgReprogNp = solicitud.evaluacionAntelacion ? (' (' + solicitud.evaluacionAntelacion.label + ')') : '';
    var tipoToastLabelNp = { reprogramacion: 'Solicitud de reprogramación enviada', cancelacion: 'Solicitud de cancelación enviada', cambio_mensajero: 'Solicitud de cambio de mensajero enviada', enroque: 'Solicitud de intercambio de turno enviada' }[tipo];
    toast('warn', tipoToastLabelNp, route.id + toastMsgReprogNp + ' — a la espera de respuesta de ' + getMensajero(route.mensajeroId).aliado + '.');
    closeModal();
    syncAndRender(true);
  });

  document.getElementById('btnNuevoUsuario').addEventListener('click', openUsuarioModal);
  refreshUsuarioModalCatalogos();
  document.querySelectorAll('.usuario-rol-check').forEach(function (c) { c.addEventListener('change', refreshUsuarioAsignacion); });
  document.getElementById('formUsuario').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('users.manage')) return;
    var editId = document.getElementById('usuarioEditId').value;
    var nombre = document.getElementById('usuarioNombre').value.trim();
    /* Ver requerimiento "Verificación de creación de Nuevo Usuario": el correo se normaliza a minúsculas una
       sola vez, aquí mismo, para que quede así en state.users/Supabase desde el origen -- antes solo se
       comparaba en minúsculas (duplicados, login) pero se guardaba tal cual lo tipeara Admin, abriendo la
       puerta a inconsistencias de mayúsculas/minúsculas entre pantallas. */
    var email = document.getElementById('usuarioEmail').value.trim().toLowerCase();
    var roles = usuarioRolesSeleccionados();
    if (!nombre || !email) return;
    if (!roles.length) { document.getElementById('usuarioRolesError').hidden = false; return; }
    document.getElementById('usuarioRolesError').hidden = true;
    if (state.users.some(function (u) { return u.email.toLowerCase() === email.toLowerCase() && u.id !== editId; })) {
      toast('warn', 'Correo ya registrado', 'Ya existe un usuario con este correo corporativo.');
      return;
    }
    var sede = roles.indexOf('BODEGA') !== -1 ? document.getElementById('usuarioSede').value : undefined;
    var aliado = roles.indexOf('ALIADO') !== -1 ? document.getElementById('usuarioAliado').value : undefined;
    if (editId) {
      var existente = state.users.find(function (u) { return u.id === editId; });
      if (!existente) return;
      existente.nombre = nombre; existente.email = email; existente.roles = roles; existente.avatarInitials = initialsOf(nombre);
      if (sede !== undefined) existente.sede = sede; else delete existente.sede;
      if (aliado !== undefined) existente.aliado = aliado; else delete existente.aliado;
      persistUsers();
      registrarEventoSeguridad('edicion', email, 'Se editó la cuenta de ' + nombre + ' (' + roles.join(' + ') + ') -- actualizado por ' + state.user.nombre + '.');
      toast('ok', 'Usuario actualizado', nombre + ' se actualizó correctamente.');
    } else {
      /* Ver requerimiento "Eliminación del Sistema de Activación por Enlace/Token -- Creación Directa con
         Clave Temporal": se retiró el flujo de invitación/token (fallaba en producción para varios usuarios
         pendientes). Protocolo único para TODOS los roles, incluido BODEGA: la cuenta nace ACTIVA de
         inmediato con la misma clave temporal fija -- el usuario entra por el login normal con esa clave y
         el Modal de Cambio Obligatorio ya existente (ver startSession) lo obliga a definir la suya propia en
         su primer ingreso, sin depender de ningún enlace ni correo. */
      var nuevo = {
        id: nextUserId(), nombre: nombre, email: email, roles: roles, avatarInitials: initialsOf(nombre),
        activo: true, modulosDeshabilitados: [], modulosAdicionales: [],
        status: 'ACTIVE', password: CLAVE_TEMPORAL_USUARIO_NUEVO, mustChangePassword: true, isTemporaryPassword: true
      };
      if (sede !== undefined) nuevo.sede = sede;
      if (aliado !== undefined) nuevo.aliado = aliado;
      state.users.push(nuevo);
      persistUsers();
      /* Ver nota "Supabase": de inmediato -- otro dispositivo podría intentar iniciar sesión con esta cuenta
         en cualquier momento, no puede esperar al autoguardado de 30s. */
      scPushRows('app_users', [nuevo]);
      registrarEventoSeguridad('creacion', email, 'Se creó la cuenta de ' + nombre + ' (' + roles.join(' + ') + '), activa de inmediato con clave temporal -- solicitado por ' + state.user.nombre + '. Deberá cambiarla en su primer inicio de sesión.');
      toast('ok', 'Usuario creado', nombre + ' fue registrado como ' + roles.join(' + ') + ' y ya puede iniciar sesión con la clave temporal ' + CLAVE_TEMPORAL_USUARIO_NUEVO + '.');
    }
    closeModal();
    renderUsuarios();
  });
  document.getElementById('formPermisos').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('users.manage')) return;
    var userId = document.getElementById('permisosUserId').value;
    var u = state.users.find(function (x) { return x.id === userId; });
    if (!u) return;
    var disabled = [];
    var adicionales = [];
    document.querySelectorAll('#permisosList [data-view-row]').forEach(function (row) {
      var viewId = row.dataset.viewRow;
      var cb = row.querySelector('input[type=checkbox]');
      if (!cb.checked) disabled.push(viewId);
      if (row.dataset.adicional === '1') adicionales.push(viewId);
    });
    u.modulosDeshabilitados = disabled;
    u.modulosAdicionales = adicionales;
    persistUsers();
    toast('ok', 'Permisos actualizados', 'Los módulos activos de ' + u.nombre + ' fueron actualizados.');
    closeModal();
    renderUsuarios();
  });
  document.getElementById('btnPermisosAgregarModulo').addEventListener('click', agregarModuloAdicionalGestion);
  ['userSearch', 'userFilterRol', 'userFilterEstado'].forEach(function (id) {
    var el = document.getElementById(id);
    el.addEventListener(el.tagName === 'SELECT' ? 'change' : 'input', renderUsuarios);
  });
  document.getElementById('userFilterClear').addEventListener('click', function () {
    document.getElementById('userSearch').value = ''; document.getElementById('userFilterRol').value = ''; document.getElementById('userFilterEstado').value = '';
    renderUsuarios();
  });

  document.getElementById('btnNuevoVehiculo').addEventListener('click', function () { openVehiculoModal(null, null); });
  document.getElementById('formVehiculo').addEventListener('submit', function (e) {
    e.preventDefault();
    var paisOriginal = document.getElementById('tipologiaEditPais').value;
    var nombreOriginal = document.getElementById('tipologiaEditNombre').value;
    var editing = !!(paisOriginal && nombreOriginal);
    if (!canDoModule('vehiculos', editing ? 'editar' : 'crear')) return;
    var nombre = document.getElementById('vehiculoNombre').value.trim();
    var pais = document.getElementById('vehiculoPais').value;
    var capacidad = document.getElementById('vehiculoCapacidad').value.trim();
    var activa = document.getElementById('vehiculoActivo').checked;
    if (!nombre || !capacidad) return;
    var dup = state.tipologiasVehiculos.some(function (t) {
      return t.pais === pais && t.nombre.toLowerCase() === nombre.toLowerCase() && !(editing && t.pais === paisOriginal && t.nombre === nombreOriginal);
    });
    if (dup) { toast('warn', 'Tipología ya registrada', 'Ya existe una tipología "' + nombre + '" para ese país.'); return; }
    if (editing) {
      var t = state.tipologiasVehiculos.find(function (x) { return x.pais === paisOriginal && x.nombre === nombreOriginal; });
      if (!t) return;
      t.nombre = nombre; t.pais = pais; t.capacidad = capacidad; t.activa = activa;
      toast('ok', 'Tipología actualizada', nombre + ' fue actualizada correctamente.');
    } else {
      state.tipologiasVehiculos.push({ nombre: nombre, pais: pais, capacidad: capacidad, activa: activa });
      toast('ok', 'Tipología creada', nombre + ' fue añadida al catálogo.');
    }
    persistTipologiasVehiculos();
    syncVehiculosDesdeTipologias();
    closeModal();
    renderVehiculos();
  });

