  document.getElementById('formRuta').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('schedule.create')) return;
    var editId = document.getElementById('rutaEditId').value;
    var sede = document.getElementById('rutaBodega').value;
    var mensajeroId = document.getElementById('rutaMensajero').value;
    var vehiculo = document.getElementById('rutaVehiculo').value;
    var hora = document.getElementById('rutaHora').value;
    if (!mensajeroId) { toast('warn', 'Selecciona un mensajero', 'No hay mensajeros disponibles para el aliado elegido.'); return; }
    if (editId) {
      var route = state.turnos.find(function (r) { return r.id === editId; });
      /* Ver requerimiento "Optimización: Trazabilidad en Historial...", punto 1c -- misma captura de
         snapshot-antes-de-mutar que submitTurno(), para esta otra vía de edición directa de ruta. */
      var sedeAnteriorRuta = route.sede, mensajeroAnteriorIdRuta = route.mensajeroId, vehiculoAnteriorRuta = route.vehiculo, horaAnteriorRuta = route.hora;
      route.sede = sede; route.mensajeroId = mensajeroId; route.vehiculo = vehiculo; route.hora = hora;
      var cambiosRuta = [];
      if (sedeAnteriorRuta !== sede) cambiosRuta.push('Bodega: ' + sedeAnteriorRuta + ' → ' + sede);
      if (mensajeroAnteriorIdRuta !== mensajeroId) cambiosRuta.push('Mensajero: ' + getMensajero(mensajeroAnteriorIdRuta).nombre + ' → ' + getMensajero(mensajeroId).nombre);
      if (vehiculoAnteriorRuta !== vehiculo) cambiosRuta.push('Vehículo: ' + vehiculoAnteriorRuta + ' → ' + vehiculo);
      if (horaAnteriorRuta !== hora) cambiosRuta.push('Hora: ' + fmtTime12(horaAnteriorRuta) + ' → ' + fmtTime12(hora));
      if (cambiosRuta.length) {
        registrarHistorialCambio(route, { tipo: 'reasignacion_directa', accion: 'editado', motivo: cambiosRuta.join(' · '), horaAnterior: horaAnteriorRuta, horaPropuesta: hora, por: state.user.nombre });
      }
      toast('ok', 'Ruta actualizada', editId + ' fue modificada.');
    } else {
      var id = nextTurnoId();
      var nuevaRuta = { id: id, sede: sede, fecha: state.progDay === 'tomorrow' ? TOMORROW_STR : TODAY_STR, mensajeroId: mensajeroId, vehiculo: vehiculo, hora: hora, llegada: null, salida: null, justificado: false, maleta: null, retirado: false, observaciones: null };
      state.turnos.push(nuevaRuta);
      registrarCreacionTurno(nuevaRuta, state.user.nombre);
      toast('ok', 'Ruta creada', id + ' fue añadida a la Programación de Flota.');
    }
    closeModal();
    syncAndRender(true);
  });

