  document.getElementById('formRetiro').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!canDo('despacho.manage')) return;
    var routeId = document.getElementById('retiroRutaId').value;
    var route = state.turnos.find(function (r) { return r.id === routeId; });
    if (!route) return;
    var motivo = document.getElementById('retiroMotivo').value.trim();
    if (!motivo) return;
    var m = getMensajero(route.mensajeroId);
    /* Matriz de Tiempos de espera en bodega (ver bodegaEsperaTramo/classifyAuditRecord): solo aplica cuando
       el mensajero SÍ había registrado llegada — un retiro sin llegada previa sigue perteneciendo al ciclo de
       ausencia (route.retiroTramo queda null, classifyAuditRecord conserva su lógica de palabras clave). */
    var retiroToastExtra = '';
    /* Ver requerimiento "Complemento Regla de Negocio: Atribución de Responsabilidades, No Autoriza Despacho y
       Solicitud de Recurso Extraordinario": bifurcación según si el retiro presentó o no Demora en Despacho
       previa (Tramo de la Matriz de Tiempos en bodega, bodegaEsperaTramo).
       CAMINO 1 (Tramo 1 "Gabela", < 1 hora, o retiro SIN llegada previa -- sin cambios, queda intacto):
       responsabilidad del Aliado/Mensajero -- reemplazoPendienteTrasRetiro=true habilita el flujo ya
       existente de "Confirmar Reemplazo"/"Mensajero está en bodega" con SLA de 1h que, si vence, escala a
       Incumplimiento Confirmado (ver computeEstado).
       CAMINO 2 (Tramo 2 "Espera" o Tramo 3 "Espera Prolongada", >= 1 hora con llegada ya registrada):
       demora en despacho imputable a Melonn/Bodega -- reemplazoPendienteTrasRetiro queda false (el flujo
       viejo NO aplica) y, tras cerrar este modal, se abre el modal extra de Solicitud Extraordinaria de
       Recurso (ver huboDemoraPrevia/openRecursoExtraordinarioModal más abajo); esa solicitud tiene su PROPIO
       SLA de 1h que nunca escala a Incumplimiento Confirmado (ver scanRoutes) -- 0% afectación al Aliado. */
    var huboDemoraPrevia = false;
    if (route.llegada) {
      var minutosEnBodegaRetiro = minutesDiff(state.now, parseDT(route.fecha, route.llegada));
      var tramoRetiro = bodegaEsperaTramo(minutosEnBodegaRetiro);
      route.retiroTramo = tramoRetiro;
      huboDemoraPrevia = tramoRetiro !== 'gabela';
      route.reemplazoPendienteTrasRetiro = tramoRetiro === 'gabela';
      var tramoLabel = tramoRetiro === 'gabela' ? 'Gabela (< 1 hora)' : tramoRetiro === 'espera' ? 'Espera (1 a 2 horas)' : 'Espera Prolongada (≥ 2 horas)';
      retiroToastExtra = ' Tramo "' + tramoLabel + '" — ' + (tramoRetiro === 'gabela' ? 'atribuible al Aliado. El turno queda visible en Alertas para que el Aliado confirme un reemplazo.' : 'Presentó Demora en Despacho — responsabilidad de Melonn/Bodega, sin afectación al Aliado.');
    } else {
      /* Ver requerimiento "Auditoría Integral: Transmisión y Visibilidad de Alertas Multi-Rol": retirar a un
         mensajero que NUNCA registró llegada (nunca hizo check-in) no tiene "tramo de espera" que evaluar
         (no hubo Check-In, así que tampoco pudo haber Demora en Despacho -- esa requiere llegada registrada,
         ver dock_overdue en computeEstado), pero sigue dejando el turno sin cubrir -- el Aliado necesita
         enterarse y asignar un reemplazo con la misma urgencia que el Tramo 1 "Gabela". Antes esta rama nunca
         fijaba reemplazoPendienteTrasRetiro, así que alertasForScope (que exige ese flag para mostrarle
         'retirado' al rol ALIADO) nunca dejaba ver la alerta al Aliado -- Bodega/Planner sí la veían siempre
         (alertaVisibleParaRol no les exige ese flag), de ahí el síntoma reportado de "solo visible en Bodega". */
      route.reemplazoPendienteTrasRetiro = true;
      retiroToastExtra = ' El turno queda visible en Alertas para que el Aliado confirme un reemplazo.';
    }
    /* Ver requerimiento "Implementación y Estandarización de Flujo Integral: Retiro de Mensajero...": ancla
       del reloj de 1 hora de la alerta (ver computeEstado) -- independiente del tramo/llegada, siempre arranca
       en el momento exacto en que Bodega marca el retiro. Para el Camino 2 (huboDemoraPrevia) este reloj no se
       usa (reemplazoPendienteTrasRetiro queda false, ver computeEstado) -- se deja fijado igual, sin efecto,
       para no complicar la lectura del campo entre caminos. */
    route.retiroAlertaDesde = fmtTimeHM(state.now);
    route.retirado = true;
    route.observaciones = motivo;
    registrarHistorialCambio(route, { tipo: 'retiro', accion: 'retirado', motivo: motivo, horaAnterior: null, horaPropuesta: null, por: state.user.nombre });
    toast('warn', 'Mensajero retirado', route.id + ' — ' + m.nombre + ' se retiró sin cargue.' + retiroToastExtra);
    closeModal();
    syncAndRender(true);
    if (huboDemoraPrevia) openRecursoExtraordinarioModal(routeId);
  });

