    if (e.target.matches('[data-act="toggle-celular"]')) toggleCelular(e.target.dataset.id, e.target.checked);
    if (e.target.matches('[data-act="flota-propia-toggle"]')) toggleFlotaPropiaActivo(e.target.dataset.id);
